def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def perturb(solution):
        p = [random.random() for _ in range(dim)]
        step_size = 0.1 * (ub - lb)
        new_solution = solution + step_size * np.multiply(p, rng.uniform(-1, 1, size=dim))
        return clip(new_solution)

    solution = np.array([random.uniform(lb, ub) for _ in range(dim)])
    temperature = 100
    best_solution = solution.copy()
    best_fitness = func(solution)
    budget_left = budget

    while budget_left > 0:
        new_solution = perturb(solution)
        new_fitness = func(new_solution)

        if new_fitness < best_fitness or rng.random() < np.exp((best_fitness - new_fitness) / temperature):
            solution = new_solution
            best_solution = solution.copy()
            best_fitness = new_fitness

        temperature *= 0.99
        budget_left -= 1

    return best_solution

def algorithm(func, dim, lb, ub, budget, rng):
    pop_size = int(np.sqrt(budget))
    population = (ub - lb) * rng.rand(pop_size, dim) + lb
    best = None

    for _ in range(budget // 2):
        # Select parents using tournament selection
        parents = np.zeros((pop_size, dim))
        for i in range(pop_size):
            idx1, idx2 = rng.randint(0, pop_size, size=2)
            if func(population[idx1]) < func(population[idx2]):
                parents[i] = population[idx1]
            else:
                parents[i] = population[idx2]

        # Perform crossover (average of two parents)
        offspring = np.zeros((pop_size, dim))
        for i in range(pop_size):
            idx1, idx2 = rng.randint(0, pop_size, size=2)
            offspring[i] = 0.5 * (parents[idx1] + parents[idx2])

        # Perform mutation
        for i in range(pop_size):
            mutation = (ub - lb) * rng.randn(dim) + lb
            offspring[i] += 0.01 * mutation

        # Clip to bounds
        population = np.clip(offspring, lb, ub)

        # Update best solution
        candidate_best = func(population[np.argmin([func(x) for x in population])])
        if best is None or candidate_best < func(best):
            best = population[np.argmin([func(x) for x in population])]

    return np.clip(best, lb, ub)

